package main

import (
	"bufio"
	"os"
	"strconv"
	"fmt"
)

var a [9]int64
var helper SHelper

func main() {
	helper.Init()

	for k := uint64(1); k <= 8; k++ {
		l := (1 << k) - 1 // shift count type int64, must be unsigned integer		
		r := 1 << (k - 1)
		v := l * r
		a[k] = int64(v)
	}

	n := helper.ReadInt64()
	for k := int64(8); k >= 1; k-- {
		if n >= a[k] && n % a[k] == 0 {
			fmt.Println(a[k])
			return
		}
	}
}

type SHelper struct {
	file *os.File
	scanner *bufio.Scanner
}

func (this *SHelper) Init() {
	this.file = os.Stdin
	this.scanner = bufio.NewScanner(this.file)
	this.scanner.Split(bufio.ScanWords)
}

func (this *SHelper) ReadInt64() int64 {
	this.scanner.Scan()
	n, err:= strconv.ParseInt(this.scanner.Text(), 10, 64)
	if err != nil {
		panic(err)
	}
	return n
}
